<template>
  <div class="pipeline-flow" data-test="pipeline-flow">
    <!--
      The diagram scrolls in its OWN container. 14 nodes never fit a narrow
      viewport, and letting the body scroll sideways instead would move the
      whole page under the reader's cursor.
    -->
    <div class="pipeline-flow__scroll" data-test="pipeline-flow-scroll">
      <svg
        class="pipeline-flow__svg"
        :viewBox="`0 0 ${canvasWidth} ${canvasHeight}`"
        :width="canvasWidth"
        :height="canvasHeight"
        role="group"
        :aria-label="ariaLabel"
        data-test="pipeline-flow-svg"
      >
        <defs>
          <marker
            id="pipeline-flow-arrow"
            viewBox="0 0 10 10"
            refX="9"
            refY="5"
            markerWidth="6"
            markerHeight="6"
            orient="auto"
          >
            <path d="M0 0L10 5L0 10z" class="pipeline-flow__arrowhead" />
          </marker>
        </defs>

        <g
          v-for="node in nodes"
          :key="node.key"
          class="pipeline-flow__node"
          :class="[
            `pipeline-flow__node--${node.stateClass}`,
            { 'pipeline-flow__node--clickable': node.clickable },
          ]"
          :data-test="`pipeline-node-${node.key}`"
          :data-state="node.state || 'aggregate'"
          :data-provenance="node.stateProvenance"
          :tabindex="node.clickable ? 0 : -1"
          :role="node.clickable ? 'button' : undefined"
          :aria-label="
            node.clickable
              ? [node.title, node.stateText, node.detailText]
                  .filter(Boolean)
                  .join(': ')
              : undefined
          "
          @click="onNodeActivate(node)"
          @keyup.enter="onNodeActivate(node)"
          @keyup.space="onNodeActivate(node)"
        >
          <!--
            The full label, for the reader whose title did not fit the box in
            one piece. SVG <title> is the native tooltip and is read by
            assistive tech; it is only emitted when a line had to be broken,
            so the common case stays a plain node.
          -->
          <title v-if="node.titleBroken">{{ node.title }}</title>

          <!-- The connector into the next stage. -->
          <line
            v-if="node.showConnector"
            class="pipeline-flow__connector"
            :x1="node.x + boxWidth + connectorInset"
            :y1="node.y + boxHeight / 2"
            :x2="node.x + boxWidth + gap - connectorInset"
            :y2="node.y + boxHeight / 2"
            marker-end="url(#pipeline-flow-arrow)"
          />

          <!--
            Shape carries the state as well as colour: a blocking node is
            drawn with a thicker, square-cornered outline and a marker above
            it, so the diagram survives being printed in grey.
          -->
          <rect
            class="pipeline-flow__box"
            :x="node.x"
            :y="node.y"
            :width="boxWidth"
            :height="boxHeight"
            :rx="node.blocking ? 2 : 7"
          />

          <text class="pipeline-flow__index" :x="node.x + 8" :y="node.y + 14">
            {{ node.no }}
          </text>

          <text
            v-for="(line, index) in node.titleLines"
            :key="`t-${index}`"
            class="pipeline-flow__title"
            :x="node.x + boxWidth / 2"
            :y="titleBaseline(node.titleLines.length, index, node.y)"
            text-anchor="middle"
          >
            {{ line }}
          </text>

          <text
            class="pipeline-flow__state"
            :x="node.x + boxWidth / 2"
            :y="node.y + boxHeight + 14"
            text-anchor="middle"
          >
            {{ node.stateText }}
          </text>

          <text
            v-if="node.detailText"
            class="pipeline-flow__detail"
            :x="node.x + boxWidth / 2"
            :y="node.y + boxHeight + 27"
            text-anchor="middle"
          >
            {{ node.detailText }}
          </text>

          <!-- „hängt hier" — the marker that makes the stop findable at a glance. -->
          <text
            v-if="node.blocking"
            class="pipeline-flow__marker"
            :x="node.x + boxWidth / 2"
            :y="node.y - 8"
            text-anchor="middle"
            :data-test="`pipeline-node-marker-${node.key}`"
          >
            {{ blockingMarkerText }}
          </text>

          <!-- Barcode and friends: a badge ON intake, never a node of its own. -->
          <g v-if="node.signalText">
            <rect
              class="pipeline-flow__signal"
              :x="node.x + 6"
              :y="node.y + boxHeight - 16"
              :width="boxWidth - 12"
              height="13"
              rx="3"
            />
            <text
              class="pipeline-flow__signal-text"
              :x="node.x + boxWidth / 2"
              :y="node.y + boxHeight - 6"
              text-anchor="middle"
              :data-test="`pipeline-signal-${node.key}`"
            >
              {{ node.signalText }}
            </text>
          </g>

          <!-- Cluster mode: the bar, under the node it belongs to. -->
          <g v-if="node.showBar">
            <rect
              class="pipeline-flow__bar-track"
              :x="node.x"
              :y="barTop"
              :width="boxWidth"
              height="8"
              rx="4"
            />
            <rect
              class="pipeline-flow__bar-fill"
              :x="node.x"
              :y="barTop"
              :width="node.barWidth"
              height="8"
              rx="4"
              :data-test="`pipeline-bar-${node.key}`"
            />
            <text
              class="pipeline-flow__bar-label"
              :x="node.x + boxWidth / 2"
              :y="barTop + 22"
              text-anchor="middle"
              :data-test="`pipeline-bar-label-${node.key}`"
            >
              {{ node.barLabel }}
            </text>
          </g>
        </g>
      </svg>
    </div>

    <!-- The legend is not decoration: colour is never the only carrier. -->
    <ul class="pipeline-flow__legend" data-test="pipeline-flow-legend">
      <li v-for="item in legend" :key="item.state">
        <span
          class="pipeline-flow__swatch"
          :class="`pipeline-flow__swatch--${item.state}`"
          aria-hidden="true"
        />
        <span>{{ item.label }}</span>
      </li>
    </ul>
  </div>
</template>

<script lang="ts">
import { computed, defineComponent, inject, type PropType } from 'vue';
import { useTolgee } from '@tolgee/vue';
import type {
  PipelineDistribution,
  PipelineStage,
} from 'src/services/analytics/PipelineExplanationService';
import { pickText } from 'src/services/analytics/PipelineExplanationService';

/** The title run: `.pipeline-flow__title` is set at 10.5 px, weight 600. */
const TITLE_FONT_PX = 10.5;
/** `wide` box: every document-lane label (EN/DE) fits in two lines at this width. */
const WIDE_BOX = 110;

/**
 * Approximate advance width of one glyph in em for the title font. Classes,
 * not a metrics table: the point is to tell "Acknowledgement" from
 * "Klassifizierung", not to typeset. Calibrated against a canvas measurement
 * of the repository font (Geist 600, 10.5 px): "Klassifizierung" 71 px,
 * "Feldvalidierung" 65 px, "Acknowledgement" 90 px — the estimate lands at
 * 71, 73 and 90.
 */
function glyphEm(ch: string): number {
  if (ch.length > 1) return 1.0; // a grapheme cluster: emoji sequence, CJK …
  if (/[ijl!|'.,:;`\u2019\u00B7]/.test(ch)) return 0.28;
  if (/[IJ]/.test(ch)) return 0.3;
  if (/[ftr\-\u2010\u2011]/.test(ch)) return 0.36;
  if (/[cszvxy]/.test(ch)) return 0.5;
  if (/[aek]/.test(ch)) return 0.53;
  if (/[EFLTZPS]/.test(ch)) return 0.55;
  if (/[ABKRVXYHNU\u00C4\u00D6\u00DC]/.test(ch)) return 0.65;
  if (/[CDGOQ]/.test(ch)) return 0.72;
  if (/[mwMW\u2026]/.test(ch)) return 0.9;
  if (/[0-9]/.test(ch)) return 0.6;
  if (/[\u3000-\u9FFF\uAC00-\uD7AF\uFF00-\uFFEF]/.test(ch)) return 1.0;
  if (/\s/.test(ch)) return 0.28;
  if ((ch.codePointAt(0) ?? 0) > 0xffff) return 1.0;
  return 0.57;
}

/** What `Intl.Segmenter` gives us, typed narrowly and optional. */
type GraphemeSegmenter = new (
  locales: undefined,
  options: { granularity: 'grapheme' },
) => { segment(text: string): Iterable<{ segment: string }> };

/**
 * The user-perceived characters of a run, in NFC: grapheme clusters where
 * the platform can segment them (a ZWJ emoji sequence stays one unit), code
 * points otherwise (a surrogate pair is never split either way). NFC first,
 * so a decomposed „ä" measures like the composed one.
 */
function graphemes(text: string): string[] {
  const normalized = text.normalize('NFC');
  const Segmenter = (Intl as { Segmenter?: GraphemeSegmenter }).Segmenter;
  if (typeof Segmenter === 'function') {
    return Array.from(
      new Segmenter(undefined, { granularity: 'grapheme' }).segment(normalized),
      (part) => part.segment,
    );
  }
  return Array.from(normalized);
}

/**
 * Where to break a compound that does not fit: the last joint in the final
 * few glyphs before `take` that looks like one, else `take` itself.
 *
 * German stage names are compounds joined by a linking ending and the next
 * part's vowel — Lieferant·en|erkennung, Kopfdat·en|extraktion,
 * Bestellzeil·en|abgleich. Breaking there reads as a word; breaking at the
 * last glyph that fits ("Lieferantener-") reads as an accident. The joint has to be one of the linking endings, not any
 * consonant: "zeil|en" is a consonant-vowel seam too and is no joint. A
 * heuristic, not a dictionary — it only moves the break a few glyphs back,
 * and a word without such a seam is broken where it fits.
 */
function compoundJoint(points: string[], take: number): number {
  const ending = /^(en|er|es|ns|gs|ts)$/i;
  const vowel = /[aeiouäöüAEIOUÄÖÜ]/;
  for (let j = take; j >= Math.max(4, take - 6); j -= 1) {
    const tail = `${points[j - 2] ?? ''}${points[j - 1] ?? ''}`;
    if (ending.test(tail) && vowel.test(points[j])) return j;
  }
  return take;
}

/**
 * The path a document took through the pipeline — or, in cluster mode, where a
 * cluster's documents stopped (DOCB-14351).
 *
 * Options API with `defineComponent`, inline SVG, no new dependency. A graph
 * library would be three hundred kilobytes for fourteen boxes in a row, and
 * the layout here is a single multiplication.
 *
 * THE ORDER OF THE STAGES IS NOT IN THIS FILE. `stages` arrives from the API
 * already ordered by the backend's `STAGE_ORDER`, and this component renders
 * it in the order it was given. That is what makes "a change to STAGE_ORDER
 * changes the diagram without a frontend change" an actual property rather
 * than a promise: there is no list here to forget to update.
 *
 * Neither are the labels: `label`, `state_label` and `summary` all arrive
 * bilingual from the API, because they are composed server-side from a closed
 * vocabulary. Only this component's OWN chrome — the legend, the "stopped
 * here" marker — goes through Tolgee.
 *
 * Colour is never the only information carrier: a blocking node is also
 * square-cornered, more heavily stroked, and marked with a word above it, and
 * every node carries its state as text underneath.
 */
/**
 * One node's laid-out geometry and text. Spelled out rather than inferred so
 * the template's arithmetic (`node.x + boxWidth`) is type-checked instead of
 * being `unknown + number`.
 */
interface PipelineFlowNode {
  key: string;
  no: number;
  x: number;
  /** Top edge of the box — `boxTop` plus the row offset when the lane wraps. */
  y: number;
  state: string | null;
  stateProvenance: string;
  stateClass: string;
  blocking: boolean;
  showConnector: boolean;
  title: string;
  titleLines: string[];
  titleBroken: boolean;
  stateText: string;
  detailText: string;
  signalText: string;
  showBar: boolean;
  barWidth: number;
  barLabel: string;
  clickable: boolean;
  stage: PipelineStage;
}

export default defineComponent({
  name: 'PipelineFlow',

  props: {
    /** Ordered by the API. Rendered in the order given, never re-sorted. */
    stages: {
      type: Array as PropType<PipelineStage[]>,
      default: () => [],
    },
    mode: {
      type: String as PropType<'document' | 'cluster'>,
      default: 'document',
    },
    distribution: {
      type: Object as PropType<PipelineDistribution | null>,
      default: null,
    },
    /**
     * Compact is for the cluster card, where the diagram sits inside a card
     * that is already dense. It shrinks the boxes; it never drops a stage,
     * because a diagram missing stages would answer a different question.
     */
    compact: { type: Boolean, default: false },
    /**
     * Full-width boxes (110 px) that WRAP into rows when the container is
     * too narrow for one (DOCB-14569). At 62 / 84 px the English stage names
     * end in an ellipsis („E-Docume…", „Acknowl…"); at 110 px every label of
     * the 14-stage document lane fits in two full lines. The row length
     * follows the container (ResizeObserver): a wide screen shows one row,
     * the explanation page's column shows two — never a cut label, never a
     * sideways scroll. Overrides `compact`.
     */
    wide: { type: Boolean, default: false },
    /**
     * Whether `po_line_match` offers the DOCB-14348 drill-down. False (the
     * default) leaves it a normal node, which is what the story asks for
     * while that component does not exist.
     */
    poMatchDrilldown: { type: Boolean, default: false },
  },

  emits: ['stage-select', 'drilldown'],

  /**
   * The language the READER is actually reading in (DOCB-14351 follow-up).
   *
   * Not `$i18n.locale`. The application's language lives in Tolgee, and
   * `$i18n.locale` does not follow it — so the bilingual text the API composes
   * (`label`, `state_label`, `summary`, `explanation`, the evidence field
   * names) rendered ENGLISH for a reader who had switched the UI to German,
   * while this component's own chrome around it was correctly German. Measured
   * on dev 10.63.2: "Weg durch die Verarbeitung" above a diagram whose stages
   * read "Field Validation / blocked".
   *
   * Same probe-then-use shape as `IssueClusterCard`: `useTolgee` dereferences
   * the injection immediately and would throw wherever Tolgee is not installed
   * — component tests most of all, where the mocked `$i18n` is then still
   * honoured by the `locale` computed below.
   */
  setup() {
    const tolgee = inject('tolgeeContext', null)
      ? useTolgee(['language'])
      : null;
    const uiLanguage = computed(() => tolgee?.value?.getLanguage() || '');
    return { uiLanguage };
  },

  data() {
    return {
      /** Width of the scroll container, for `wide` — 0 until measured. */
      containerWidth: 0,
      resizeObserver: null as ResizeObserver | null,
    };
  },

  mounted() {
    if (!this.wide || typeof ResizeObserver === 'undefined') return;
    const el = this.$el?.querySelector?.(
      '.pipeline-flow__scroll',
    ) as HTMLElement | null;
    if (!el) return;
    this.containerWidth = el.clientWidth;
    this.resizeObserver = new ResizeObserver((entries) => {
      const width = entries[0]?.contentRect?.width;
      if (typeof width === 'number') this.containerWidth = Math.floor(width);
    });
    this.resizeObserver.observe(el);
  },

  beforeUnmount() {
    this.resizeObserver?.disconnect();
    this.resizeObserver = null;
  },

  computed: {
    /**
     * Tolgee first, `$i18n` second, English last. Tolgee codes carry a region
     * (`en-us`, `pt-br`); the API keys its bilingual text on the bare language,
     * so only the first segment is used.
     */
    locale(): string {
      const raw = String(this.uiLanguage || this.$i18n?.locale || 'en');
      return raw.split('-')[0] || 'en';
    },

    boxWidth(): number {
      if (this.wide) return WIDE_BOX;
      return this.compact ? 62 : 84;
    },

    /**
     * Nodes per row. Everything on one row unless `wide` and the container
     * is narrower than the whole lane; then as many full boxes as fit, at
     * least one. Until the container is measured (first paint, jsdom) the
     * lane is one row.
     */
    perRow(): number {
      const count = this.stages.length || 1;
      if (!this.wide || !this.containerWidth) return count;
      const fit = Math.floor(
        (this.containerWidth - 8 + this.gap) / (this.boxWidth + this.gap),
      );
      return Math.max(1, Math.min(count, fit));
    },

    rowCount(): number {
      const count = this.stages.length || 1;
      return Math.ceil(count / this.perRow);
    },

    /** Vertical distance between rows: box, state + detail lines, next row's marker. */
    rowPitch(): number {
      return this.boxHeight + 66;
    },

    /**
     * The width one title line may take inside the box, in px.
     *
     * The box is 84 px (62 px compact) and the title is set 4 px off either
     * edge. Measured against this with `titleWidth`, an estimate of the
     * Geist 600 / 10.5 px run — jsdom lays nothing out, and a character
     * count was the wrong proxy: "Acknowledgement" (15 characters) measures
     * ~90 px while "Klassifizierung" (15 characters) measures ~71 px.
     */
    titleMaxWidth(): number {
      return this.boxWidth - 8;
    },

    /**
     * Tall enough for two title lines (13 px apart, 10.5 px font) UNDER the
     * index row, with the descenders still inside the border. The old 40 px
     * compact box put the second line's baseline at +43 — below the box
     * (DOCB-14569 review: "text is not 100% in the boxes").
     */
    boxHeight(): number {
      return this.compact ? 50 : 56;
    },

    gap(): number {
      return this.compact ? 12 : 18;
    },

    /**
     * Breathing room at BOTH ends of the connector (DOCB-14448).
     *
     * The connector used to span the gap exactly, so its line started flush
     * against one box and its arrowhead ended flush against the next — the
     * arrows read as if they were welded to the boxes. Inset both ends and
     * widen the gap enough that a visible line remains: the arrowhead is
     * ~5.4px wide (markerWidth 6 at refX 9), so a bare `gap - 2 * inset` of
     * 6px would leave the head floating with no shaft.
     */
    connectorInset(): number {
      return this.compact ? 3 : 4;
    },

    boxTop(): number {
      return 26;
    },

    barTop(): number {
      return this.boxTop + this.boxHeight + 34;
    },

    isCluster(): boolean {
      return this.mode === 'cluster';
    },

    canvasWidth(): number {
      return this.perRow * (this.boxWidth + this.gap) - this.gap + 8;
    },

    canvasHeight(): number {
      if (this.isCluster) return this.barTop + 34;
      return (
        this.boxTop + (this.rowCount - 1) * this.rowPitch + this.boxHeight + 40
      );
    },

    /**
     * The largest count in the window, used as the bar scale.
     *
     * The scale is the biggest BAR, while the share on the label is the share
     * of the POPULATION — two different denominators on purpose. A bar drawn
     * against the population would be invisible for every stage but the
     * dominant one; a share computed against the biggest bar would read 100 %
     * for a stage that stopped three documents out of nine hundred.
     */
    maxBlockedCount(): number {
      return this.stages.reduce(
        (peak, stage) => Math.max(peak, Number(stage.blocked_count || 0)),
        0,
      );
    },

    nodes(): PipelineFlowNode[] {
      return this.stages.map((stage, index) => {
        const state = stage.state ?? null;
        const blocking = Boolean(stage.is_first_blocker);
        const count = Number(stage.blocked_count || 0);
        const share = stage.share_pct;
        const row = Math.floor(index / this.perRow);
        const col = index % this.perRow;
        const lastInRow = col === this.perRow - 1;
        return {
          key: stage.key,
          no: stage.no ?? index + 1,
          x: 4 + col * (this.boxWidth + this.gap),
          y: this.boxTop + row * this.rowPitch,
          state,
          stateProvenance: stage.state_provenance || 'stored',
          stateClass: this.stateClass(stage),
          blocking,
          showConnector: index < this.stages.length - 1 && !lastInRow,
          title: pickText(stage.label, this.locale),
          titleLines: this.titleLines(pickText(stage.label, this.locale)),
          titleBroken: this.titleWasBroken(pickText(stage.label, this.locale)),
          stateText: this.isCluster
            ? String(count)
            : pickText(stage.state_label, this.locale) || String(state || ''),
          detailText: this.detailText(stage),
          signalText: this.signalText(stage),
          showBar: this.isCluster,
          barWidth: this.barWidth(count),
          barLabel: share === null || share === undefined ? '—' : `${share} %`,
          clickable: this.isClickable(stage),
          stage,
        };
      });
    },

    legend(): { state: string; label: string }[] {
      // Built from what is actually on screen, so a diagram of a clean
      // document does not carry a "stopped here" swatch nothing matches.
      const present = new Set(
        this.stages.map((stage) => this.stateClass(stage)),
      );
      const all = [
        { state: 'passed', label: this.$t('pipeline_flow_legend_passed') },
        { state: 'blocked', label: this.$t('pipeline_flow_legend_blocked') },
        { state: 'skipped', label: this.$t('pipeline_flow_legend_skipped') },
        {
          state: 'not-reached',
          label: this.$t('pipeline_flow_legend_not_reached'),
        },
        { state: 'unknown', label: this.$t('pipeline_flow_legend_unknown') },
        {
          state: 'aggregate',
          label: this.$t('pipeline_flow_legend_blocked_count'),
        },
      ];
      return all.filter((item) => present.has(item.state));
    },

    blockingMarkerText(): string {
      return this.isCluster
        ? this.$t('pipeline_flow_most_documents_stop_here')
        : this.$t('pipeline_flow_stopped_here');
    },

    ariaLabel(): string {
      return this.isCluster
        ? this.$t('pipeline_flow_aria_cluster')
        : this.$t('pipeline_flow_aria_document');
    },
  },

  methods: {
    /**
     * Baseline of title line `index` of `count`: a single line sits centred
     * in the space below the index row; two lines start higher so the second
     * one, descenders included, stays 6+ px above the bottom edge.
     */
    titleBaseline(count: number, index: number, top?: number): number {
      const first =
        count > 1 ? (this.compact ? 26 : 30) : this.compact ? 32 : 36;
      return (top ?? this.boxTop) + first + index * 13;
    },

    /**
     * The visual class for a stage.
     *
     * `blocked` and `failed` share one class deliberately — a reader asks
     * "did it stop here", not "which of our two stopping statuses was it" —
     * while the exact status stays readable as text under the node and in the
     * `data-state` attribute.
     */
    stateClass(stage: PipelineStage): string {
      if (this.isCluster) return 'aggregate';
      const state = stage.state;
      if (state === 'blocked' || state === 'failed') return 'blocked';
      if (state === 'passed') return 'passed';
      if (state === 'skipped' || state === 'not_applicable') return 'skipped';
      if (state === 'not_reached') return 'not-reached';
      return 'unknown';
    },

    /**
     * Estimated rendered width of a title run, in px.
     *
     * A per-glyph-class table for a humanist sans at 600 / 10.5 px: narrow
     * strokes (i, l, j, punctuation) around 0.28 em, wide ones (m, w, M, W)
     * around 0.85 em, capitals ~0.68 em, the rest ~0.56 em, CJK a full em.
     * Calibrated so that "Klassifizierung" comes out ~71 px and
     * "Acknowledgement" ~90 px, which is what a canvas measurement of the
     * repository font gives. An estimate, and stated as one — it decides the
     * wrap, and the full label rides on the node whenever it had to be cut.
     */
    titleWidth(text: string): number {
      let em = 0;
      for (const ch of graphemes(String(text || ''))) {
        em += glyphEm(ch);
      }
      return em * TITLE_FONT_PX;
    },

    /**
     * The label, wrapped to at most two lines that each fit the box.
     *
     * Splitting at word boundaries alone was the defect: the German stage
     * names are single compounds („Bestellzeilenabgleich", 21 characters),
     * so they came out as one line and overflowed into the neighbouring node.
     * Segments are words and the pieces of hyphenated words (the hyphen
     * stays with its piece, and only a piece we split off glues to the next
     * one — a hyphen the label itself ends a word with keeps its space).
     * Packed greedily by estimated width; a segment wider than a whole line
     * is broken with a hyphen at the last code point that still fits. Two
     * lines is the space the box has; anything beyond is cut with an
     * ellipsis. Whenever a segment had to be broken or cut, the full label
     * rides on the node as its tooltip (`wrapTitle().broken`).
     */
    titleLines(label: string): string[] {
      return this.wrapTitle(label).lines;
    },

    /** True when the title did not fit the box as the label was written. */
    titleWasBroken(label: string): boolean {
      return this.wrapTitle(label).broken;
    },

    wrapTitle(label: string): { lines: string[]; broken: boolean } {
      const max = this.titleMaxWidth;
      const fits = (text: string) => this.titleWidth(text) <= max;
      const segments: Array<{ text: string; glue: boolean }> = [];
      for (const word of String(label || '')
        .split(/\s+/)
        .filter(Boolean)) {
        const pieces = word.split(/(?<=-)/).filter(Boolean);
        pieces.forEach((piece, index) =>
          segments.push({ text: piece, glue: index < pieces.length - 1 }),
        );
      }
      if (!segments.length) return { lines: ['—'], broken: false };

      const lines: string[] = [];
      let current = '';
      let glueNext = false;
      let broken = false;
      const flush = () => {
        if (current) lines.push(current);
        current = '';
      };

      for (const segment of segments) {
        let text = segment.text;
        // A segment wider than a whole line: break it with a hyphen at the
        // last code point that still fits — code points, so a surrogate
        // pair is never split.
        while (!fits(text)) {
          flush();
          const points = graphemes(text);
          let take = points.length - 1;
          while (take > 1 && !fits(`${points.slice(0, take).join('')}-`)) {
            take -= 1;
          }
          // Prefer a compound joint — but only while the rest still fits on
          // the next line. A joint that forces a third line trades a whole,
          // readable word for an ellipsis, which is the worse deal.
          const joint = compoundJoint(points, take);
          if (joint < take && fits(points.slice(joint).join(''))) {
            take = joint;
          }
          // A glyph wider than the whole box still has to move somewhere;
          // one glyph per line is the floor that keeps this loop finite.
          take = Math.max(1, take);
          lines.push(`${points.slice(0, take).join('')}-`);
          text = points.slice(take).join('');
          broken = true;
        }
        const joiner = current ? (glueNext ? '' : ' ') : '';
        const candidate = `${current}${joiner}${text}`;
        if (current && !fits(candidate)) {
          flush();
          current = text;
        } else {
          current = candidate;
        }
        glueNext = segment.glue;
      }
      flush();

      if (lines.length <= 2) return { lines, broken };
      // Two lines is all the box has: cut the second one with an ellipsis.
      // A hyphen we inserted at the end of that line would read "anten-…";
      // the ellipsis already says the word goes on.
      const points = graphemes(lines[1].replace(/-$/, ''));
      let take = points.length;
      while (take > 0 && !fits(`${points.slice(0, take).join('')}…`)) {
        take -= 1;
      }
      return {
        lines: [lines[0], `${points.slice(0, take).join('')}…`],
        broken: true,
      };
    },

    /**
     * The one extra fact under a node. In document mode the reason code of a
     * stage that stopped the document; nothing otherwise, because a diagram
     * that annotates every node annotates none of them.
     */
    detailText(stage: PipelineStage): string {
      if (this.isCluster) return '';
      if (!stage.reason_code) return '';
      if (stage.state !== 'blocked' && stage.state !== 'failed') return '';
      return this.translateEnum('touchless_reason_', stage.reason_code);
    },

    /** The badge inside the node — barcode on intake. */
    signalText(stage: PipelineStage): string {
      const signal = (stage.signals || [])[0];
      if (!signal) return '';
      // 'unknown' means nothing recorded a barcode observation. Drawing a
      // badge for it would put a claim on screen that nobody made.
      if (signal.state === 'unknown') return '';
      return pickText(signal.label, this.locale);
    },

    barWidth(count: number): number {
      if (!this.maxBlockedCount || !count) return 0;
      return Math.max(
        2,
        Math.round((count / this.maxBlockedCount) * this.boxWidth),
      );
    },

    /**
     * A node is clickable when there is somewhere to go: any stage in cluster
     * mode (it opens the cluster filtered to that stage), and `po_line_match`
     * in document mode once DOCB-14348 exists.
     */
    isClickable(stage: PipelineStage): boolean {
      if (this.isCluster) return Number(stage.blocked_count || 0) > 0;
      return this.poMatchDrilldown && stage.key === 'po_line_match';
    },

    onNodeActivate(node: PipelineFlowNode): void {
      if (!node.clickable) return;
      const stage = node.stage;
      if (!this.isCluster && stage.key === 'po_line_match') {
        this.$emit('drilldown', stage);
        return;
      }
      this.$emit('stage-select', stage);
    },

    /**
     * i18n with a fallback to the raw enum, the same helper the rest of the
     * panel uses. A backend that adds a reason code renders the code rather
     * than a missing-key placeholder.
     */
    translateEnum(prefix: string, value: string | null | undefined): string {
      const raw = String(value || '');
      if (!raw) return '';
      const key = `${prefix}${raw.toLowerCase()}`;
      const translated = this.$t(key);
      return translated === key ? raw : translated;
    },
  },
});
</script>

